args.query:
\d+ api.*
select schemaname,tablename,policyname,cmd,roles,qual,with_check from pg_policies;
select n.nspname,c.relname,c.relkind,c.relrowsecurity,c.relforcerowsecurity,pg_get_userbyid(c.relowner),c.reloptions from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('api','public') and c.relkind in ('r','v');
select tgname,tgrelid::regclass,pg_get_triggerdef(oid) from pg_trigger where not tgisinternal;
select proname,pronamespace::regnamespace,prosecdef,pg_get_functiondef(oid) from pg_proc where pronamespace::regnamespace::text in ('api','public');

select grantee,table_name,privilege_type from information_schema.role_table_grants where table_schema='api' and grantee not in ('postgres') order by 2,1,3;
select grantee,table_name,column_name,privilege_type from information_schema.column_privileges where table_schema='api' and grantee in ('applicant','expert','fund_admin','PUBLIC','anon','authenticator') and table_name='application' order by 1,3,4;
select * from api.status order by ord; select * from api.app_user;
select rolname,rolbypassrls from pg_roles where rolname in ('applicant','expert','fund_admin','authenticator');
select count(*) from api.application;

alter table api.application add column internal_score numeric;
grant select(internal_score), update(internal_score) on api.application to expert;
revoke all(internal_score) on api.application from applicant, public;
select grantee,privilege_type from information_schema.column_privileges where table_schema='api' and table_name='application' and column_name='internal_score';
